      + field('Secret refs (comma-separated)', '<input id="f-refs" type="text" value="' + esc((m.secret_refs || []).join(', ')) + '" placeholder="BACKUP_S3_KEY, BACKUP_S3_SECRET">', 'Names of vaulted secrets to inject as env.')
