  var state = {
    path: '/',
    entries: [],
    busy: false,
    error: '',
    selected: {},   // name -> true
    search: '',
    menuFor: null,  // entry name whose 3-dot menu is open
    modal: null,    // {kind:'create'|'upload'|'rename', ...}
    createTab: 'file',
    uploadTab: 'local',
    uploadPct: 0,
    uploadLabel: '',
    urlPct: 0,
    root: '/'
  };

  function flash(ok, msg) {
    try { sdk.toast(msg, ok ? 'success' : 'error'); } catch (e) { /* ignore */ }
  }

