          + '<span class="ks-badge ks-mono" style="margin-top:4px">' + esc(p.user || '—') + '</span></div>'
          + '<div style="display:flex;align-items:flex-start;gap:8px"><span class="ks-mono ks-muted" style="font-size:12px;flex-shrink:0">Command:</span>'
