      + '<div id="term-path" class="ks-mono" style="display:flex;align-items:center;gap:6px;padding:6px 10px;background:var(--ks-term-bg,#1e1e1e);border-bottom:1px solid var(--ks-card-border);font-size:11px;color:var(--ks-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'
      + '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="width:11px;height:11px;flex-shrink:0;opacity:0.7"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/><path d="M8 13h4"/><path d="M12 9v8"/></svg>'
